                    await connection.ExecuteAsync(InsertHistorySql(databaseType), new
                    {
                        SeedFile = fileName,
                        ScriptHash = hash,
                        AppliedAtUtc = DateTime.UtcNow,
                        InsertedRows = insertedRows,
                        ElapsedMs = fileStopwatch.ElapsedMilliseconds
