        private static bool IsGeneratedPortalNavigationSeedFile(string fileName)
        {
            if (string.IsNullOrWhiteSpace(fileName))
                return false;

            return fileName.Contains("IdentityDefaultData", StringComparison.OrdinalIgnoreCase)
                   || fileName.Contains("ModulesAndModelsData", StringComparison.OrdinalIgnoreCase)
                   || fileName.Contains("PortalPageGrantsData", StringComparison.OrdinalIgnoreCase)
                   || fileName.Contains("ApiKeysData", StringComparison.OrdinalIgnoreCase);
