    /// <summary>
    /// Points orphan single-column FK values at an existing parent row (lowest PK).
    /// Needed after restart loops where IDENTITY/serial gaps leave seed FKs (1..N) dangling.
    /// Works for mssql, postgresql, and mysql.
    /// </summary>
    private static async Task RepairOrphanForeignKeysAsync(
        System.Data.Common.DbConnection connection,
        string databaseType,
        ILogger logger)
    {
        try
        {
            var foreignKeys = (await LoadSingleColumnForeignKeysAsync(connection, databaseType)).ToList();
            if (foreignKeys.Count == 0)
                return;

            var repaired = 0;
            foreach (var fk in foreignKeys)
            {
                var sql = BuildOrphanForeignKeyRepairSql(databaseType, fk);
                if (string.IsNullOrWhiteSpace(sql))
                    continue;

                repaired += await connection.ExecuteAsync(sql);
            }

            logger.LogInformation(
                "QuickCode seed repaired orphan foreign-key values for {DatabaseType} ({ConstraintCount} constraint(s), {UpdatedRows} row update(s)).",
                databaseType,
                foreignKeys.Count,
                repaired);
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "QuickCode seed could not repair orphan foreign-key values for {DatabaseType}.", databaseType);
        }
    }

    private sealed record ForeignKeyColumnRef(
        string ChildTable,
        string ChildColumn,
        string ParentTable,
        string ParentColumn);

    private static async Task<IEnumerable<ForeignKeyColumnRef>> LoadSingleColumnForeignKeysAsync(
        System.Data.Common.DbConnection connection,
        string databaseType)
    {
        var sql = databaseType.ToLowerInvariant() switch
        {
            "mssql" => """
                SELECT
                    OBJECT_NAME(fk.parent_object_id) AS ChildTable,
                    pc.name AS ChildColumn,
                    OBJECT_NAME(fk.referenced_object_id) AS ParentTable,
                    rc.name AS ParentColumn
                FROM sys.foreign_keys AS fk
                INNER JOIN sys.foreign_key_columns AS fkc ON fkc.constraint_object_id = fk.object_id
                INNER JOIN sys.columns AS pc ON pc.object_id = fkc.parent_object_id AND pc.column_id = fkc.parent_column_id
                INNER JOIN sys.columns AS rc ON rc.object_id = fkc.referenced_object_id AND rc.column_id = fkc.referenced_column_id
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM sys.foreign_key_columns AS fkc2
                    WHERE fkc2.constraint_object_id = fk.object_id
                      AND fkc2.constraint_column_id > 1
                );
                """,
            "postgresql" => """
                SELECT
                    c.relname AS "ChildTable",
                    a.attname AS "ChildColumn",
                    cf.relname AS "ParentTable",
                    af.attname AS "ParentColumn"
                FROM pg_constraint AS con
                INNER JOIN pg_class AS c ON c.oid = con.conrelid
                INNER JOIN pg_class AS cf ON cf.oid = con.confrelid
                INNER JOIN LATERAL unnest(con.conkey) WITH ORDINALITY AS ck(attnum, ord) ON TRUE
                INNER JOIN LATERAL unnest(con.confkey) WITH ORDINALITY AS fk(attnum, ord) ON fk.ord = ck.ord
                INNER JOIN pg_attribute AS a ON a.attrelid = con.conrelid AND a.attnum = ck.attnum AND NOT a.attisdropped
                INNER JOIN pg_attribute AS af ON af.attrelid = con.confrelid AND af.attnum = fk.attnum AND NOT af.attisdropped
                WHERE con.contype = 'f'
                  AND cardinality(con.conkey) = 1;
                """,
            "mysql" => """
                SELECT
                    kcu.TABLE_NAME AS ChildTable,
                    kcu.COLUMN_NAME AS ChildColumn,
                    kcu.REFERENCED_TABLE_NAME AS ParentTable,
                    kcu.REFERENCED_COLUMN_NAME AS ParentColumn
                FROM information_schema.KEY_COLUMN_USAGE AS kcu
                INNER JOIN information_schema.TABLE_CONSTRAINTS AS tc
                    ON tc.CONSTRAINT_SCHEMA = kcu.CONSTRAINT_SCHEMA
                   AND tc.CONSTRAINT_NAME = kcu.CONSTRAINT_NAME
                   AND tc.TABLE_NAME = kcu.TABLE_NAME
                   AND tc.CONSTRAINT_TYPE = 'FOREIGN KEY'
                WHERE kcu.CONSTRAINT_SCHEMA = DATABASE()
                  AND kcu.REFERENCED_TABLE_NAME IS NOT NULL
                  AND NOT EXISTS (
                      SELECT 1
                      FROM information_schema.KEY_COLUMN_USAGE AS k2
                      WHERE k2.CONSTRAINT_SCHEMA = kcu.CONSTRAINT_SCHEMA
                        AND k2.CONSTRAINT_NAME = kcu.CONSTRAINT_NAME
                        AND k2.TABLE_NAME = kcu.TABLE_NAME
                        AND k2.ORDINAL_POSITION > 1
                  );
                """,
            _ => null
        };

        if (sql is null)
            return [];

        return await connection.QueryAsync<ForeignKeyColumnRef>(sql);
    }

    private static string BuildOrphanForeignKeyRepairSql(string databaseType, ForeignKeyColumnRef fk)
    {
        var childTable = Quote(fk.ChildTable, databaseType);
        var childColumn = Quote(fk.ChildColumn, databaseType);
        var parentTable = Quote(fk.ParentTable, databaseType);
        var parentColumn = Quote(fk.ParentColumn, databaseType);

        return databaseType.ToLowerInvariant() switch
        {
            "mssql" => $"""
                UPDATE c SET {childColumn} = p.Id
                FROM {childTable} AS c
                CROSS APPLY (
                    SELECT TOP (1) {parentColumn} AS Id
                    FROM {parentTable}
                    ORDER BY {parentColumn}
                ) AS p
                WHERE NOT EXISTS (
                    SELECT 1 FROM {parentTable} AS r WHERE r.{parentColumn} = c.{childColumn}
                )
                AND EXISTS (SELECT 1 FROM {parentTable});
                """,
            "postgresql" => $"""
                UPDATE {childTable} AS c
                SET {childColumn} = p.id
                FROM (
                    SELECT {parentColumn} AS id
                    FROM {parentTable}
                    ORDER BY {parentColumn}
                    LIMIT 1
                ) AS p
                WHERE NOT EXISTS (
                    SELECT 1 FROM {parentTable} AS r WHERE r.{parentColumn} = c.{childColumn}
                )
                AND EXISTS (SELECT 1 FROM {parentTable});
                """,
            "mysql" => $"""
                UPDATE {childTable} AS c
                INNER JOIN (
                    SELECT {parentColumn} AS id
                    FROM {parentTable}
                    ORDER BY {parentColumn}
                    LIMIT 1
                ) AS p
                SET c.{childColumn} = p.id
                WHERE NOT EXISTS (
                    SELECT 1 FROM {parentTable} AS r WHERE r.{parentColumn} = c.{childColumn}
                );
                """,
            _ => string.Empty
        };
    }

    /// <summary>
    /// Defers FK enforcement for circular NOT NULL references (e.g. Location.ManagerUser ↔ User.Location).
    /// </summary>
    private static async Task SetForeignKeyChecksAsync(
        System.Data.Common.DbConnection connection,
        string databaseType,
        bool enabled,
        ILogger logger)
    {
        try
        {
            switch (databaseType.ToLowerInvariant())
            {
                case "mssql":
                    if (enabled)
                    {
                        const string withCheck = """
                            DECLARE @sql nvarchar(max) = N'';
                            SELECT @sql += N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id))
                                + N'.' + QUOTENAME(OBJECT_NAME(parent_object_id))
                                + N' WITH CHECK CHECK CONSTRAINT ' + QUOTENAME(name) + N';'
                            FROM sys.foreign_keys
                            WHERE is_disabled = 1;
                            IF LEN(@sql) > 0 EXEC sys.sp_executesql @sql;
                            """;
                        try
                        {
                            await connection.ExecuteAsync(withCheck);
                        }
                        catch (Exception validateEx)
                        {
                            logger.LogWarning(
                                validateEx,
                                "WITH CHECK re-enable failed; enabling foreign keys without validating existing rows.");
                            const string noCheck = """
                                DECLARE @sql nvarchar(max) = N'';
                                SELECT @sql += N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id))
                                    + N'.' + QUOTENAME(OBJECT_NAME(parent_object_id))
                                    + N' WITH NOCHECK CHECK CONSTRAINT ' + QUOTENAME(name) + N';'
                                FROM sys.foreign_keys
                                WHERE is_disabled = 1;
                                IF LEN(@sql) > 0 EXEC sys.sp_executesql @sql;
                                """;
                            await connection.ExecuteAsync(noCheck);
                        }
                    }
                    else
                    {
                        const string disable = """
                            DECLARE @sql nvarchar(max) = N'';
                            SELECT @sql += N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id))
                                + N'.' + QUOTENAME(OBJECT_NAME(parent_object_id))
                                + N' NOCHECK CONSTRAINT ' + QUOTENAME(name) + N';'
                            FROM sys.foreign_keys
                            WHERE is_disabled = 0;
                            IF LEN(@sql) > 0 EXEC sys.sp_executesql @sql;
                            """;
                        await connection.ExecuteAsync(disable);
                    }

                    break;
                case "postgresql":
                    await connection.ExecuteAsync(enabled
                        ? "SET session_replication_role = DEFAULT;"
                        : "SET session_replication_role = replica;");
                    break;
                case "mysql":
                    await connection.ExecuteAsync(enabled
                        ? "SET FOREIGN_KEY_CHECKS = 1;"
                        : "SET FOREIGN_KEY_CHECKS = 0;");
                    break;
                default:
                    return;
            }

            logger.LogInformation(
                "QuickCode seed foreign-key checks {State} for {DatabaseType}.",
                enabled ? "re-enabled" : "disabled",
                databaseType);
        }
        catch (Exception ex)
        {
            logger.LogWarning(
                ex,
                "Could not {Action} foreign-key checks for {DatabaseType}.",
                enabled ? "re-enable" : "disable",
                databaseType);
        }
    }

    private static async Task<int> ApplySeedFileAsync(
        System.Data.Common.DbConnection connection,
        System.Data.Common.DbTransaction transaction,
        string databaseType,
        string content,
        ILogger logger)
    {
        var root = JObject.Parse(content).ToObject<Dictionary<string, List<Dictionary<string, object?>>>>();
        if (root is null)
            return 0;

        var insertedRows = 0;
        foreach (var (tableName, rows) in root)
        {
            var tableStopwatch = Stopwatch.StartNew();
            var uniqueColumns = ResolveUniqueColumns(tableName, rows);
            var existingKeys = await LoadExistingKeysAsync(connection, transaction, databaseType, tableName, uniqueColumns);
            var insertedInTable = 0;
            var rowsToInsert = new List<Dictionary<string, object?>>(rows.Count);

            foreach (var row in rows)
            {
                var normalized = NormalizeRow(row);
                if (normalized.Count == 0)
                    continue;

                var rowKey = BuildRowKey(normalized, uniqueColumns);
                if (existingKeys.Contains(rowKey))
                    continue;

                rowsToInsert.Add(normalized);
                existingKeys.Add(rowKey);
                insertedRows++;
                insertedInTable++;
            }

            if (rowsToInsert.Count > 0)
            {
                var binaryColumns = await LoadBinaryColumnNamesAsync(connection, transaction, databaseType, tableName);
                if (binaryColumns.Count > 0)
                {
                    foreach (var row in rowsToInsert)
                        CoerceBinaryColumns(row, binaryColumns);
                }

                var identityColumns = await LoadIdentityColumnNamesAsync(connection, transaction, databaseType, tableName);
                var insertIncludesIdentity = identityColumns.Count > 0
                    && rowsToInsert[0].Keys.Any(identityColumns.Contains);

                if (insertIncludesIdentity && databaseType.Equals("mssql", StringComparison.OrdinalIgnoreCase))
                {
                    await connection.ExecuteAsync(
                        $"SET IDENTITY_INSERT {Quote(tableName, databaseType)} ON;",
                        transaction: transaction);
                }

                try
                {
                    var batchSize = GetBatchSize(rowsToInsert[0].Count);
                    foreach (var batch in ChunkRows(rowsToInsert, batchSize))
                    {
                        var (batchSql, batchParameters) = BuildInsertBatchSql(
                            databaseType,
                            tableName,
                            batch,
                            insertIncludesIdentity);
                        await connection.ExecuteAsync(batchSql, batchParameters, transaction);
                    }
                }
                finally
                {
                    if (insertIncludesIdentity && databaseType.Equals("mssql", StringComparison.OrdinalIgnoreCase))
                    {
                        await connection.ExecuteAsync(
                            $"SET IDENTITY_INSERT {Quote(tableName, databaseType)} OFF;",
                            transaction: transaction);
                        await connection.ExecuteAsync(
                            $"DBCC CHECKIDENT ('{tableName.Replace("'", "''", StringComparison.Ordinal)}', RESEED);",
                            transaction: transaction);
                    }
                }
            }

            var skippedInTable = rows.Count - insertedInTable;
            if (tableStopwatch.ElapsedMilliseconds > 250 || insertedInTable > 0)
            {
                // Log potentially expensive table processing with counts for easier diagnosis.
                logger.LogInformation(
                    "QuickCode seed table {TableName}: inserted {InsertedRows}, skipped {SkippedRows}, elapsed: {ElapsedMs} ms.",
                    tableName,
                    insertedInTable,
                    skippedInTable,
                    tableStopwatch.ElapsedMilliseconds);
            }
        }

        return insertedRows;
    }

    private static string[] ResolveUniqueColumns(
        string tableName,
        List<Dictionary<string, object?>> rows)
    {
        var mapped = UniqueColumnMap.GetValueOrDefault(tableName);
        if (mapped is not null)
            return mapped;

        var firstRow = rows.FirstOrDefault();
        if (firstRow is null)
            return [];

        var normalizedKeys = NormalizeRow(firstRow).Keys.ToArray();
        var idColumn = normalizedKeys.FirstOrDefault(key =>
            key.Equals("Id", StringComparison.OrdinalIgnoreCase) ||
            key.Equals($"{tableName}Id", StringComparison.OrdinalIgnoreCase));
        if (!string.IsNullOrWhiteSpace(idColumn))
            return [idColumn];

        var keyColumn = normalizedKeys.FirstOrDefault(key => key.Equals("Key", StringComparison.OrdinalIgnoreCase));
        if (!string.IsNullOrWhiteSpace(keyColumn))
            return [keyColumn];

        var nameColumn = normalizedKeys.FirstOrDefault(key => key.Equals("Name", StringComparison.OrdinalIgnoreCase));
        if (!string.IsNullOrWhiteSpace(nameColumn))
            return [nameColumn];

        return normalizedKeys;
    }

    private static async Task<HashSet<string>> LoadExistingKeysAsync(
        System.Data.Common.DbConnection connection,
        System.Data.Common.DbTransaction transaction,
        string databaseType,
        string tableName,
        string[] uniqueColumns)
    {
        if (uniqueColumns.Length == 0)
            return [];

        var selectColumns = string.Join(", ", uniqueColumns.Select(column => Quote(column, databaseType)));
        var sql = $"SELECT {selectColumns} FROM {Quote(tableName, databaseType)};";
        var records = await connection.QueryAsync(sql, transaction: transaction);
        var keys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var record in records)
        {
            if (record is not IDictionary<string, object?> values)
                continue;

            var key = string.Join("|", uniqueColumns.Select(column =>
            {
                var value = values.TryGetValue(column, out var exact)
                    ? exact
                    : values.FirstOrDefault(pair => string.Equals(pair.Key, column, StringComparison.OrdinalIgnoreCase)).Value;
                return value?.ToString() ?? "<null>";
            }));
            keys.Add(key);
        }

        return keys;
    }

    private static string BuildRowKey(Dictionary<string, object?> row, string[] uniqueColumns) =>
        string.Join("|", uniqueColumns.Select(column => row.TryGetValue(column, out var value) ? value?.ToString() ?? "<null>" : "<missing>"));

    private static Dictionary<string, object?> NormalizeRow(Dictionary<string, object?> row)
    {
        return row.ToDictionary(
            pair => pair.Key,
            pair => pair.Value switch
            {
                JValue value => value.Value,
                JToken token => token.ToString(Newtonsoft.Json.Formatting.None),
                _ => pair.Value
            },
            StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// IMAGE/FILE/VARBINARY columns must receive byte[] — legacy seed JSON may contain fake text strings.
    /// </summary>
    private static async Task<HashSet<string>> LoadBinaryColumnNamesAsync(
        System.Data.Common.DbConnection connection,
        System.Data.Common.DbTransaction transaction,
        string databaseType,
        string tableName)
    {
        var sql = databaseType.ToLowerInvariant() switch
        {
            "mssql" => """
                       SELECT COLUMN_NAME
                       FROM INFORMATION_SCHEMA.COLUMNS
                       WHERE TABLE_NAME = @TableName
                         AND DATA_TYPE IN ('varbinary', 'binary', 'image')
                       """,
            "postgresql" => """
                            SELECT column_name AS COLUMN_NAME
                            FROM information_schema.columns
                            WHERE table_name = @TableName
                              AND data_type IN ('bytea')
                            """,
            "mysql" => """
                       SELECT COLUMN_NAME
                       FROM INFORMATION_SCHEMA.COLUMNS
                       WHERE TABLE_NAME = @TableName
                         AND DATA_TYPE IN ('blob', 'tinyblob', 'mediumblob', 'longblob', 'binary', 'varbinary')
                       """,
            _ => null
        };

        if (sql is null)
            return [];

        var names = await connection.QueryAsync<string>(sql, new { TableName = tableName }, transaction);
        return names.ToHashSet(StringComparer.OrdinalIgnoreCase);
    }

    private static void CoerceBinaryColumns(Dictionary<string, object?> row, HashSet<string> binaryColumns)
    {
        foreach (var column in binaryColumns)
        {
            if (!row.TryGetValue(column, out var value) || value is null || value is byte[])
                continue;

            if (value is string text)
            {
                if (string.IsNullOrWhiteSpace(text))
                {
                    row[column] = Array.Empty<byte>();
                    continue;
                }

                try
                {
                    row[column] = Convert.FromBase64String(text);
                }
                catch (FormatException)
                {
                    // Fake text from older seed generators — store empty blob instead of failing nvarchar→varbinary.
                    row[column] = Array.Empty<byte>();
                }
            }
        }
    }

    private static int GetBatchSize(int columnCount)
    {
        if (columnCount <= 0)
            return 1;

        var safeByParameters = Math.Max(1, TargetMaxParametersPerBatch / columnCount);
        return Math.Max(1, Math.Min(MaxBatchRows, safeByParameters));
    }

    private static IEnumerable<List<Dictionary<string, object?>>> ChunkRows(
        List<Dictionary<string, object?>> rows,
        int batchSize)
    {
        for (var i = 0; i < rows.Count; i += batchSize)
        {
            yield return rows.GetRange(i, Math.Min(batchSize, rows.Count - i));
        }
    }

    private static async Task<HashSet<string>> LoadIdentityColumnNamesAsync(
        System.Data.Common.DbConnection connection,
        System.Data.Common.DbTransaction transaction,
        string databaseType,
        string tableName)
    {
        var sql = databaseType.ToLowerInvariant() switch
        {
            "mssql" => """
                       SELECT c.name
                       FROM sys.columns AS c
                       INNER JOIN sys.tables AS t ON t.object_id = c.object_id
                       WHERE t.name = @TableName
                         AND c.is_identity = 1
                       """,
            "postgresql" => """
                            SELECT a.attname
                            FROM pg_class AS c
                            INNER JOIN pg_attribute AS a ON a.attrelid = c.oid
                            WHERE c.relname = @TableName
                              AND a.attnum > 0
                              AND NOT a.attisdropped
                              AND a.attidentity <> ''
                            """,
            "mysql" => """
                       SELECT COLUMN_NAME
                       FROM INFORMATION_SCHEMA.COLUMNS
                       WHERE TABLE_SCHEMA = DATABASE()
                         AND TABLE_NAME = @TableName
                         AND EXTRA LIKE '%auto_increment%'
                       """,
            _ => null
        };

        if (sql is null)
            return [];

        var names = await connection.QueryAsync<string>(sql, new { TableName = tableName }, transaction);
        return names.ToHashSet(StringComparer.OrdinalIgnoreCase);
    }

    private static (string Sql, DynamicParameters Parameters) BuildInsertBatchSql(
        string databaseType,
        string tableName,
        List<Dictionary<string, object?>> rows,
        bool insertIncludesIdentity = false)
    {
        if (rows.Count == 0)
            throw new ArgumentException("Batch cannot be empty.", nameof(rows));

        var columnList = rows[0].Keys.ToList();
        var names = string.Join(", ", columnList.Select(column => Quote(column, databaseType)));
        var parameters = new DynamicParameters();
        var valueRows = new List<string>(rows.Count);

        for (var rowIndex = 0; rowIndex < rows.Count; rowIndex++)
        {
            var row = rows[rowIndex];
            var rowParameterNames = new List<string>(columnList.Count);
            for (var colIndex = 0; colIndex < columnList.Count; colIndex++)
            {
                var column = columnList[colIndex];
                var parameterName = $"p_{rowIndex}_{colIndex}";
                rowParameterNames.Add("@" + parameterName);
                parameters.Add(parameterName, row.TryGetValue(column, out var value) ? value : null);
            }

            valueRows.Add($"({string.Join(", ", rowParameterNames)})");
        }

        var overriding = insertIncludesIdentity
                         && databaseType.Equals("postgresql", StringComparison.OrdinalIgnoreCase)
            ? " OVERRIDING SYSTEM VALUE"
            : string.Empty;

        var sql = $"INSERT INTO {Quote(tableName, databaseType)} ({names}){overriding} VALUES {string.Join(", ", valueRows)};";
        return (sql, parameters);
    }

    private static IEnumerable<string> FindSeedFiles()
    {
        var baseDirectory = AppContext.BaseDirectory;
        if (!Directory.Exists(baseDirectory))
            return [];

        return Directory
            .GetFiles(baseDirectory, "*.json", SearchOption.AllDirectories)
            .Where(path => path.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
                .Any(part => part.Equals("InitialData", StringComparison.OrdinalIgnoreCase)))
            .OrderBy(Path.GetFileName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(path => path, StringComparer.OrdinalIgnoreCase);
    }

    private static string CreateHistoryTableSql(string databaseType) => databaseType.ToLowerInvariant() switch
    {
        "mssql" => $"""
                   IF OBJECT_ID(N'dbo.{HistoryTableName}', N'U') IS NULL
                   BEGIN
                       CREATE TABLE [dbo].[{HistoryTableName}] (
                           [SeedFile] nvarchar(300) NOT NULL,
                           [ScriptHash] nvarchar(128) NOT NULL,
                           [AppliedAtUtc] datetime2 NOT NULL,
                           [InsertedRows] int NOT NULL,
                           [ElapsedMs] bigint NOT NULL,
                           CONSTRAINT [PK_{HistoryTableName}] PRIMARY KEY ([SeedFile], [ScriptHash])
                       );
                   END;
                   IF COL_LENGTH(N'dbo.{HistoryTableName}', N'ElapsedMs') IS NULL
                   BEGIN
                       ALTER TABLE [dbo].[{HistoryTableName}] ADD [ElapsedMs] bigint NOT NULL CONSTRAINT [DF_{HistoryTableName}_ElapsedMs] DEFAULT (0);
                   END;
                   """,
        "postgresql" => $"""
                        CREATE TABLE IF NOT EXISTS "{HistoryTableName}" (
                            "SeedFile" varchar(300) NOT NULL,
                            "ScriptHash" varchar(128) NOT NULL,
                            "AppliedAtUtc" timestamp with time zone NOT NULL,
                            "InsertedRows" integer NOT NULL,
                            "ElapsedMs" bigint NOT NULL DEFAULT 0,
                            CONSTRAINT "PK_{HistoryTableName}" PRIMARY KEY ("SeedFile", "ScriptHash")
                        );
                        ALTER TABLE "{HistoryTableName}" ADD COLUMN IF NOT EXISTS "ElapsedMs" bigint NOT NULL DEFAULT 0;
                        """,
        "mysql" => $"""
                   CREATE TABLE IF NOT EXISTS `{HistoryTableName}` (
                       `SeedFile` varchar(300) NOT NULL,
                       `ScriptHash` varchar(128) NOT NULL,
                       `AppliedAtUtc` datetime(6) NOT NULL,
                       `InsertedRows` int NOT NULL,
                       `ElapsedMs` bigint NOT NULL DEFAULT 0,
                       CONSTRAINT `PK_{HistoryTableName}` PRIMARY KEY (`SeedFile`, `ScriptHash`)
                   );
                   ALTER TABLE `{HistoryTableName}` ADD COLUMN IF NOT EXISTS `ElapsedMs` bigint NOT NULL DEFAULT 0;
                   """,
        _ => throw new NotSupportedException($"Database type '{databaseType}' is not supported.")
    };

    private static string SelectHistoryCountSql(string databaseType) => databaseType.ToLowerInvariant() switch
    {
        "mssql" => $"SELECT COUNT(*) FROM [dbo].[{HistoryTableName}] WHERE [SeedFile] = @SeedFile AND [ScriptHash] = @ScriptHash;",
        "postgresql" => $"SELECT COUNT(*) FROM \"{HistoryTableName}\" WHERE \"SeedFile\" = @SeedFile AND \"ScriptHash\" = @ScriptHash;",
        "mysql" => $"SELECT COUNT(*) FROM `{HistoryTableName}` WHERE `SeedFile` = @SeedFile AND `ScriptHash` = @ScriptHash;",
        _ => throw new NotSupportedException($"Database type '{databaseType}' is not supported.")
    };

    private static string InsertHistorySql(string databaseType) => databaseType.ToLowerInvariant() switch
    {
        "mssql" => $"INSERT INTO [dbo].[{HistoryTableName}] ([SeedFile], [ScriptHash], [AppliedAtUtc], [InsertedRows], [ElapsedMs]) VALUES (@SeedFile, @ScriptHash, @AppliedAtUtc, @InsertedRows, @ElapsedMs);",
        "postgresql" => $"INSERT INTO \"{HistoryTableName}\" (\"SeedFile\", \"ScriptHash\", \"AppliedAtUtc\", \"InsertedRows\", \"ElapsedMs\") VALUES (@SeedFile, @ScriptHash, @AppliedAtUtc, @InsertedRows, @ElapsedMs);",
        "mysql" => $"INSERT INTO `{HistoryTableName}` (`SeedFile`, `ScriptHash`, `AppliedAtUtc`, `InsertedRows`, `ElapsedMs`) VALUES (@SeedFile, @ScriptHash, @AppliedAtUtc, @InsertedRows, @ElapsedMs);",
        _ => throw new NotSupportedException($"Database type '{databaseType}' is not supported.")
    };

    private static string Quote(string identifier, string databaseType) => databaseType.ToLowerInvariant() switch
    {
        "mssql" => $"[{identifier.Replace("]", "]]", StringComparison.Ordinal)}]",
        "postgresql" => $"\"{identifier.Replace("\"", "\"\"", StringComparison.Ordinal)}\"",
        "mysql" => $"`{identifier.Replace("`", "``", StringComparison.Ordinal)}`",
        _ => identifier
    };

    private static string Hash(string value)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(value));
        return Convert.ToHexString(bytes);
    }
}
